//! aot_rt: what compiled Move code (generated by `deepwave-aot`, see aot_emit.zig) is built from.
//!
//! A compiled function replaces `Session.stepRun` for one Move function: a state machine with one
//! case per bytecode offset that runs the SAME instruction implementation as the interpreter
//! (`Session.op`, which charges gas, checks types and moves values) with the instruction known at
//! compile time, so the dispatch, the operand decoding and the branch targets fold away and the
//! next pc of every straight-line instruction and every branch is a constant jump. Gas, abort
//! locations, stack effects and error offsets are therefore identical by construction: the
//! generated code never charges or decides anything itself. Calls and returns, which switch frames,
//! leave through `slow` into the interpreter's own `step`.
const std = @import("std");
const move_format = @import("move_format");
const interp = @import("interp.zig");

pub const ff = move_format.file_format;
pub const Session = interp.Session;
pub const Frame = interp.Frame;
pub const StepError = interp.StepError;
pub const RunFn = interp.AotFn;

/// One compiled function of a module.
pub const FnEntry = struct { def_idx: u16, name: []const u8, run: RunFn };

/// One compiled module: the module's self address and name, the digest of its bytecode
/// (`digestModule`) and its compiled functions. A loaded module uses the entry only when the
/// digest of its own bytecode equals `digest`.
pub const Entry = struct {
    address: [32]u8,
    name: []const u8,
    digest: [32]u8,
    fns: []const FnEntry,
};

/// Runs instruction `ins` at offset `pc` of the current frame like `stepRun` does: the pc is stored
/// first (error locations read it), a failing instruction gets its location, nothing else.
/// Returns the next pc the interpreter would run (only branches and VariantSwitch differ from pc+1).
pub inline fn exec(s: *Session, f: *Frame, comptime ins: ff.Instr, comptime pc: u16) StepError!u16 {
    f.pc = pc;
    return @call(.always_inline, Session.op, .{ s, f, ins, pc }) catch |e| {
        if (e == error.Vm) s.atFrame(f);
        return e;
    };
}

/// Leaves compiled code at `pc` (a call, a return, or a pc past the code) into the interpreter.
pub inline fn slow(s: *Session, f: *Frame, pc: u16) StepError!bool {
    f.pc = pc;
    return s.stepUntraced();
}

/// Digest of what a compiled module is specialized on: its identity (address, name) and every
/// function's instruction stream and jump tables, fully decoded fields, so the same bytecode always
/// gives the same digest and any change to a compiled function's code changes it. Everything else
/// the instructions read (constants, handles, signatures) is looked up in the loaded module when
/// the compiled code runs, so it needs no part in the key.
pub fn digestModule(cm: *const ff.CompiledModule) [32]u8 {
    var h = std.crypto.hash.blake2.Blake2b256.init(.{});
    h.update("deepwave-aot-v1");
    h.update(cm.selfAddress());
    const name = cm.selfName();
    hashInt(&h, u32, @intCast(name.len));
    h.update(name);
    hashInt(&h, u32, @intCast(cm.function_defs.len));
    for (cm.function_defs) |fd| {
        const c = fd.code orelse {
            h.update(&.{0});
            continue;
        };
        h.update(&.{1});
        hashInt(&h, u32, @intCast(cm.signatures[cm.function_handles[fd.function].parameters].len));
        hashInt(&h, u32, @intCast(cm.signatures[c.locals].len));
        hashInt(&h, u32, @intCast(c.code.len));
        for (c.code) |ins| {
            h.update(&.{@intFromEnum(ins.op)});
            hashInt(&h, u16, ins.idx);
            hashInt(&h, u64, ins.imm);
        }
        hashInt(&h, u32, @intCast(c.jump_tables.len));
        for (c.jump_tables) |jt| {
            hashInt(&h, u16, jt.head_enum);
            hashInt(&h, u32, @intCast(jt.offsets.len));
            for (jt.offsets) |o| hashInt(&h, u16, o);
        }
    }
    var out: [32]u8 = undefined;
    h.final(&out);
    return out;
}

fn hashInt(h: *std.crypto.hash.blake2.Blake2b256, comptime T: type, v: T) void {
    var b: [@sizeOf(T)]u8 = undefined;
    std.mem.writeInt(T, &b, v, .little);
    h.update(&b);
}
